#!/usr/bin/env bash
# The Homebrew formula of the native joust (ADR-0017 D7), and JOUST's version order. Used by release.yml's homebrew
# job (the only code that job runs) and tested on every pull request by homebrew-formula-test.sh.
#
#   homebrew-formula.sh check <version>                 exit 0 if <version> is in JOUST's version grammar
#   homebrew-formula.sh compare <a> <b>                 prints -1, 0 or 1: <a> before, equal to, after <b>
#   homebrew-formula.sh current <formula.rb>            the version a formula pins ("" when the file does not exist)
#   homebrew-formula.sh write <version> <sha-macos-aarch64> <sha-linux-x86_64> <sha-linux-arm64> <out.rb>
#
# The grammar is X.Y.Z with optional -<letters><digits> parts (0.1.0-pre1-rc7, 0.1.0-pre1-dev1, 0.2.0-alpha2). The
# order: X.Y.Z numerically; then the parts one by one, letters as text and digits as numbers; and when one version's
# parts are a proper prefix of the other's, the shorter is later (0.1.0-pre1 is the release of 0.1.0-pre1-rcN, and 0.1.0
# the release of all its pre-releases). SemVer orders these names wrongly (pre1-rc10 before pre1-rc9).
set -euo pipefail

GRAMMAR='^[0-9]+\.[0-9]+\.[0-9]+(-[a-z]+[0-9]+)*$'

check() {
  [[ "$1" =~ $GRAMMAR ]]
}

compare() {
  local a=$1 b=$2
  check "$a" || { echo "not a JOUST version: $a" >&2; return 2; }
  check "$b" || { echo "not a JOUST version: $b" >&2; return 2; }
  python3 -I - "$a" "$b" <<'PY'
import re, sys
def key(v):
    base, *parts = v.split('-')
    nums = [int(x) for x in base.split('.')]
    return nums, [(re.match(r'[a-z]+', p).group(), int(re.search(r'[0-9]+$', p).group())) for p in parts]
def cmp(a, b):
    (na, pa), (nb, pb) = key(a), key(b)
    if na != nb:
        return -1 if na < nb else 1
    for x, y in zip(pa, pb):
        if x != y:
            return -1 if x < y else 1
    if len(pa) == len(pb):
        return 0
    return 1 if len(pa) < len(pb) else -1   # the shorter is the release of the longer
print(cmp(sys.argv[1], sys.argv[2]))
PY
}

current() {
  local f=$1
  [[ -f "$f" ]] || { echo ""; return 0; }
  sed -nE 's/^[[:space:]]*version "([^"]*)"[[:space:]]*$/\1/p' "$f" | head -n 1
}

write() {
  local v=$1 mac=$2 lx=$3 la=$4 out=$5 base
  check "$v" || { echo "not a JOUST version: $v" >&2; return 2; }
  for s in "$mac" "$lx" "$la"; do
    [[ "$s" =~ ^[0-9a-f]{64}$ ]] || { echo "not a SHA-256: $s" >&2; return 2; }
  done
  base="https://github.com/bloxbean/joust/releases/download/v${v}"
  mkdir -p "$(dirname "$out")"
  cat > "$out" <<EOF
# Generated by bloxbean/joust .github/scripts/homebrew-formula.sh for joust ${v}. Do not edit by hand.
class Joust < Formula
  desc "JOUST: create and build Cardano state-contract projects, Java or npm"
  homepage "https://github.com/bloxbean/joust"
  version "${v}"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "${base}/joust-${v}-macos-aarch64.zip"
      sha256 "${mac}"
    end
  end

  on_linux do
    if Hardware::CPU.intel?
      url "${base}/joust-${v}-linux-x86_64.zip"
      sha256 "${lx}"
    elsif Hardware::CPU.arm?
      url "${base}/joust-${v}-linux-arm64.zip"
      sha256 "${la}"
    end
  end

  def install
    bin.install "joust"
  end

  test do
    assert_match "joust #{version} (native)", shell_output("#{bin}/joust --version")
  end
end
EOF
}

cmd=${1:?usage: homebrew-formula.sh check|compare|current|write ...}
shift
case "$cmd" in
  check) check "$@" ;;
  compare) compare "$@" ;;
  current) current "$@" ;;
  write) write "$@" ;;
  *) echo "unknown command: $cmd" >&2; exit 2 ;;
esac
